query DataSecurityViolationGetQuery($violationId: String!) {
  policyViolation(
    violationId: $violationId
    policyTypes: [POLICY_TYPE_DATAGOV]
  ) {
    ...DataAtRiskPanelFragment
    status
    violationSeverity
    policyViolationId
    createdAt
    lastUpdatedAt
    resourceId
    policy {
      policyId
      name
      description
      policyCategory
      policySeverity
      containsAccessFilters
      __typename
    }
    remediations {
      remediationId
      state
      remediationDetails {
        details {
          ticketNumber
          ticketUrl
          __typename
        }
        __typename
      }
      __typename
    }
    resourceMetadata {
      metadata {
        ... on CommonAssetMetadata {
          platform
          cloudAccountInfo {
            accountName
            __typename
          }
          objectType
          clusterInfo {
            clusterName
            clusterUuid
            __typename
          }
          creationTime
          lastAccessTime
          snapshotTimestamp
          physicalHost
          name
          isDeleted
          region
          __typename
        }
      }
      __typename
    }
    __typename
  }
}

fragment SensitiveHitsChartFragment on DataGovViolationDetails {
  snapshotId
  violatedSensitiveHits
  violatedNoRiskSensitiveHits
  violatedLowRiskSensitiveHits
  violatedMediumRiskSensitiveHits
  violatedHighRiskSensitiveHits
  __typename
}

fragment DataAtRiskPanelFragment on PolicyViolation {
  details {
    ...SensitiveHitsChartFragment
    ... on DataGovViolationDetails {
      dataCategories {
        id
        name
        totalViolatedHits
        __typename
      }
      dataTypes {
        id
        name
        totalViolatedHits
        __typename
      }
      mipLabels {
        id
        totalViolatedHits
        name
        __typename
      }
      documentTypes {
        id
        name
        totalViolatedHits
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

mutation DownloadFullSnapshotResultsCsvMutation($filters: DownloadResultsCsvFiltersInput, $snappableFid: String!, $snapshotFid: String!) {
  downloadSnapshotResultsCsv(
    snappableFid: $snappableFid
    snapshotFid: $snapshotFid
    downloadFilter: $filters
  ) {
    isSuccessful
    __typename
  }
}

