query DSPMViolationFileListQuery(
  $first: Int!
  $after: String
  $snappableFid: String!
  $snapshotFid: String!
  $filters: ListFileResultFiltersInput
  $sort: FileResultSortInput
  $timezone: String!
) {
  policyObj(snappableFid: $snappableFid, snapshotFid: $snapshotFid) {
    id: snapshotFid
    fileResultConnection(
      first: $first
      after: $after
      filter: $filters
      sort: $sort
      timezone: $timezone
    ) {
      edges {
        cursor
        node {
          nativePath
          stdPath
          filename
          mode
          size
          directory
          createdBy
          modifiedBy
          hits {
            totalHits
            violations
            __typename
          }
          __typename
        }
        __typename
      }
      pageInfo {
        startCursor
        endCursor
        hasNextPage
        hasPreviousPage
        __typename
      }
      hasLatestData
      __typename
    }
    __typename
  }
}

